import { MsgMap } from '@/pages/Agentic/type';
import { Delete, Get, Post } from '../requestInstance';

export const getExchangeId = (
  payload: { sessionId: string },
  baseUrl: string,
) => {
  return Post<typeof payload, string>(
    '/api/plugin/exchange',
    payload,
    '获取 exchangeId 失败',
    {
      baseUrl,
    },
  );
};

export interface ModelProperties {
  [key: string]: {
    vision: boolean;
    desc: string;
    name: string;
    agenticEnable: boolean;
  };
}
export interface CancelRunningPayload {
  session_id: string;
  editor_url: string;
  access_token: string;
  model_configuration: Record<string, any>;
}

// 手动中断会话
export const cancelRunning = (
  payload: CancelRunningPayload,
  baseUrl: string,
) => {
  return Post<typeof payload, never>(
    '/api/agentic/cancel_running_event',
    payload,
    '中断失败',
    {
      baseUrl,
      silent: true,
    },
  );
};

// 提供商的密钥信息
interface ProviderKey {
  key_name: string;
  key_value: string;
  key_description: string;
}

// AI 模型信息
interface AIModule {
  name: string;
  max_tokens: string;
  context_window: string;
  supports_images: string;
  supports_prompt_cache: string;
  input_price: string;
  output_price: string;
  cache_writes_price: string;
  cache_reads_price: string;
  provider: string;
}

// 单个提供商的完整信息
export interface ProviderInfo {
  provider: ProviderKey[];
  modules: AIModule[];
  default_model: string;
}

// 所有提供商的集合
export interface ProviderObj {
  [providerName: string]: ProviderInfo;
}
export interface ProvidersData {
  providers: ProviderObj;
  default_provider: string;
  default_model: string;
}

// 获取通道选择列表
export const getChannelList = (baseUrl: string) => {
  return Get<never, ProvidersData>(
    '/api/plugin/llm_properties/get',
    undefined,
    '获取模型数据失败',
    {
      baseUrl,
    },
  );
};

