interface CheckoutPayload {
  session_id: string;
  exchange_id: string;
  project_id: string;
  edit_url: string;
}
export interface DiffMsgObj {
  old_content: string;
  new_content: string;
  session_old_content: string;
  file_path: string;
  diff: string;
  session_diff: string;
}

interface CheckoutRes {
  delete: Array<string>;
  modify: Array<DiffMsgObj>;
}

// 撤销操作
