// 因为vscode与webview通信是完全隔离，并不像jetbrains那样可以通过传递一个callback 回调函数的方式来实现接受插件的返回结果，所以针对vscode单独封装一套包含cmdId的指令方式，在vscode指令发送消息的基础上实现请求响应机制

import { noop } from 'lodash';

const pendingRequests = new Map();
let postMessage = noop;
try {
  postMessage = acquireVsCodeApi().postMessage;
} catch (e) {}

interface VscodeCallbackProps {
  message: JsBridgeMessage;
  successCallback?: (...args: any[]) => void;
  errorCallback?: (...args: any[]) => void;
}

// 监听从 VS Code 插件返回的消息
window.addEventListener('message', (e: MessageEvent<JsBridgeMessage>) => {
  const { data: message } = e;
  if (!message?.vscodeCallbackId) {
    return;
  }
  const { vscodeCallbackId } = message;
  // 获取对应的 Promise 并解析
  const { successCallback } = pendingRequests.get(vscodeCallbackId);
  message.data = JSON.stringify(message.data);
  successCallback(JSON.stringify(message));

  // 删除已完成的请求
  pendingRequests.delete(vscodeCallbackId);
});

export const vscodePostMessageFn = (props: VscodeCallbackProps) => {
  const vscodeCallbackId = Date.now();
  const { message, successCallback, errorCallback } = props;
  postMessage({ ...message, vscodeCallbackId });
  // 将当前请求保存到 pendingRequests 中
  pendingRequests.set(vscodeCallbackId, { successCallback, errorCallback });
};

export const vscodePostMessage = (payload: string) => {
  postMessage(JSON.parse(payload));
};
