import { createWithEqualityFn } from 'zustand/traditional';
import { actions } from './actions';
import { initialState } from './initialState';
import { StoreActions, StoreState } from './types';

// 使用最新的 createWithEqualityFn
const useAgenticStore = createWithEqualityFn<StoreState & StoreActions>()(
  (set, get, store) => ({
    ...initialState,
    ...actions(set, get, store),
  }),
);

export default useAgenticStore;
