import { AgentStreamMessage, ChatStreamMessage } from '@/interface/global';
import { getHeaders } from '@/utils/getHeaders';
import streamAsyncIterable from '@/utils/streamAsyncIterable';
import { history, request } from '@umijs/max';
import { noop } from 'lodash';
import jsBridgePostMessage from '../JsBridge/jsBridgePostMessage';
import { RawResponseType } from './requestConfig';

interface ParsedResponse<T> {
  data: T;
  success: true;
}

interface ParsedError extends RawResponseType {
  success: false;
}

export const myRequest = async <T extends any, K extends any>(
  url: string,
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' = 'GET',
  payload?: T,
  errmsg: string | false = false,
  options: Record<string, any> = {},
): Promise<ParsedResponse<K> | ParsedError> => {
  const {
    headers: uniqueHeaders = {},
    silent = false,
    baseUrl,
  } = options as {
    headers?: Record<string, string>;
    silent?: boolean; // 新增字段
    baseUrl?: string; // 自定义 baseUrl
  };
  const headers = getHeaders({
    ...uniqueHeaders,
    'Content-Type': 'application/json',
  });

  const requestUrl = `${baseUrl}${url}`;

  try {
    const res = await request<RawResponseType<K>>(requestUrl, {
      method,
      ...(method === 'GET' ? { params: payload } : { data: payload }),
      ...options,
      headers,
      credentials: 'include',
    });

    // @ts-ignore
    if (res.errno === 0 || res.success || !res.error) {
      return { ...res, success: true };
    } else {
      if (res.errno === 7000) {
        jsBridgePostMessage({
          command: 'loginFailed',
        });
        history.replace('/welcome');
      } else if (!silent) {
        jsBridgePostMessage({
          command: 'alert',
          data: {
            type: 'error',
            title: `webview： ${url} 请求失败`,
            content: errmsg || res.error || res?.message || '',
          },
        });
      }
      return { ...res, success: false, data: {} };
    }
  } catch (err) {
    if (errmsg !== false && !silent) {
      jsBridgePostMessage({
        command: 'alert',
        data: {
          type: 'error',
          title: `webview： ${url} 请求失败`,
          content: errmsg,
        },
      });
    }
    return { success: false, data: {}, errno: -1, error: errmsg || '请求失败' };
  }
};

export function Get<T extends any, K extends any>(
  url: string,
  params?: T,
  errmsg?: string | false,
  options?: Record<string, unknown>,
): Promise<ParsedResponse<K> | ParsedError> {
  return myRequest<T, K>(url, 'GET', params, errmsg, options);
}

export function Post<T extends any, K extends any>(
  url: string,
  data?: T,
  errmsg?: string | false,
  options?: Record<string, unknown>,
): Promise<ParsedResponse<K> | ParsedError> {
  return myRequest<T, K>(url, 'POST', data, errmsg, options);
}

export function Put<T extends any, K extends any>(
  url: string,
  data?: T,
  errmsg?: string | false,
  options?: Record<string, unknown>,
): Promise<ParsedResponse<K> | ParsedError> {
  return myRequest<T, K>(url, 'PUT', data, errmsg, options);
}

export function Delete<T extends any, K extends any>(
  url: string,
  data?: T,
  errmsg?: string | false,
  options?: Record<string, unknown>,
): Promise<ParsedResponse<K> | ParsedError> {
  return myRequest<T, K>(url, 'DELETE', data, errmsg, options);
}

export class FetchSSE {
  private url: string;
  private onMessage?: (msg: ChatStreamMessage) => void;
  private onAgentMessage?: (msg: ChatStreamMessage) => void;
  private onError?: (e?: Error | string) => void;
  private onFinish?: (finish: string) => void;
  private onFinally?: () => void; // 新增属性
  private method: 'POST';
  private data?: any;
  private headers: Record<string, string> = {};
  private abortController: AbortController;
  private loading: boolean;
  private type: 'chat' | 'agent';
  onLoadingStatusChange: (loading: boolean) => void;
  // private readonly DEFAULT_URL = `${BASE_URL}/api/agentic/agent_session_chat`;

  constructor(payload: {
    url?: string;
    sideCarPort?: string;
    onMessage?: (msg: ChatStreamMessage) => void;
    onAgentMessage?: (msg: AgentStreamMessage) => void;
    onError?: (e: Error | string) => void;
    onFinish?: (finish: string) => void;
    onFinally?: () => void; // 新增参数
    onLoadingStatusChange?: (loading: boolean) => void;
    data?: any;
    headers?: Record<string, string>;
    type: 'chat' | 'agent';
  }) {
    const {
      url,
      sideCarPort,
      onMessage = noop,
      onAgentMessage = noop,
      onError = noop,
      onFinish = noop,
      onFinally = noop,
      onLoadingStatusChange = noop,
      data = {},
      headers = {},
      type,
    } = payload;
    this.url = `http://localhost:${sideCarPort}${url}`;
    this.onMessage = onMessage;
    this.onAgentMessage = onAgentMessage;
    this.onError = onError;
    this.onFinish = onFinish;

    this.method = 'POST';
    this.data = data;
    this.abortController = new AbortController();
    this.loading = false;
    this.type = type;
    this.onLoadingStatusChange = onLoadingStatusChange;
    this.headers = getHeaders({
      ...headers,
      'content-type': 'application/json',
    });
    this.onFinally = onFinally;
    this.start();
  }

  public async start() {
    this.loading = true;
    this.onLoadingStatusChange(true);
    try {
      const res = await fetch(this.url, {
        method: this.method,
        headers: this.headers,
        credentials: 'include',
        signal: this.abortController.signal,
        body: JSON.stringify(this.data),
      });
      if (!res.ok) {
        this.onError?.('请求错误');
        console.error('chat stream error', res);
        return;
      }
      // 缓存的上次消息最后一条不完整的数据
      let lastData = '';
      for await (const chunk of streamAsyncIterable(res.body!)) {
        const str = new TextDecoder().decode(chunk);
        try {
          // 先判断一下返回有没有报错
          const data = JSON.parse(str);
          if (data?.errno !== 0) {
            this.onError?.(`请求错误: ${data?.error}\n错误码: ${data?.errno}`);
            return;
          }
        } catch (e) {
          // 如果在这捕获到了错误，说明返回的是正常的数据，无需处理，直接跳过
        }
        // 拼接上一次的数据
        const fullData = `${lastData}${str}`;
        // 重置缓存的数据
        lastData = '';
        // 处理数据
        fullData
          .split('\n\n')
          .filter(Boolean)
          .map((data) => data.replace(/^data:/g, ''))
          .map((data, index, array) => {
            try {
              return JSON.parse(`${data}`);
            } catch (e) {
              // 如果最后一条消息不完整，就拼接到下一次的数据中
              if (index === array.length - 1) {
                lastData = data;
              } else {
                console.error({ e, data, fullData });
              }
              return '';
            }
          })
          // 过滤掉上一步解析失败的数据，防止后续报错
          .filter(Boolean)
          .forEach((data) => {
            if (!this.abortController.signal.aborted) {
              if (this.type === 'chat') {
                this.onMessage?.(data);
              } else if (this.type === 'agent') {
                this.onAgentMessage?.(data);
              }
            }
          });
      }
    } catch (e: any) {
      if (e?.name === 'AbortError') {
        this?.onFinish?.('abort');
      } else {
        console.error(e);
        this.onError?.('请求失败，请重试');
      }
    } finally {
      this.onLoadingStatusChange(false);
      this.loading = false;
      this.onFinally?.(); // 调用finally回调
    }
  }

  public abort() {
    this.abortController.abort();
    this.loading = false;
    this.onLoadingStatusChange(false);
    setTimeout(() => this.onFinally?.(), 0);
  }

  public get isLoading() {
    return this.loading;
  }
}
