import { noop } from 'lodash';
import { vscodePostMessage, vscodePostMessageFn } from './vscodeCallbackEvent';
let jsBridgePostMessageFn: JsBridgePostMessage = noop;
let jsBridgePostMessageWithCallbackFn: JsBridgePostMessageWithCallback = noop;
let isPostMessageBindingSuccessful = false; // 插件通信方法是否绑定成功

// 绑定vscode和jetbrains两种插件的通信方法
// 其中 jetbrains 插件因为自身限制，注入方法比较复杂，首次可能会出现不成功的情况，所以每次执行jsBridgePostMessage都会检测是否要重新绑定
const setBridgeFn = () => {
  if (window?.pluginConfig?.ide === 'vscode') {
    // 处理 vscode 注入方法的绑定逻辑
    try {
      jsBridgePostMessageFn = vscodePostMessage;
      isPostMessageBindingSuccessful = true;
      console.log(
        '【绑定 vscode 通信方法成功】：postMessage',
        vscodePostMessage,
      );
    } catch (e) {
      console.error(e);
      console.log('【绑定 vscode 通信方法失败】：postMessage', e);
    }
  } else {
    // 处理 jetbrains 注入方法的绑定逻辑
    try {
      if (!window?.JavaPanelBridge) {
        console.log('【绑定 jetbrains 通信方法失败】：window.JavaPanelBridge');
        return;
      }
      const { sendMessage = noop, sendMessageWithCallback = noop } =
        window?.JavaPanelBridge ?? {};
      jsBridgePostMessageFn = sendMessage;
      jsBridgePostMessageWithCallbackFn = sendMessageWithCallback;
      isPostMessageBindingSuccessful = true;
      console.log(
        '【绑定 jetbrains 通信方法成功】：window.JavaPanelBridge',
        window?.JavaPanelBridge,
      );
    } catch (e) {
      console.log('【绑定 jetbrains 通信方法失败】：window.JavaPanelBridge', e);
      console.error(e);
    }
  }
};

setBridgeFn();

const jsBridgePostMessage = (
  payload: JsBridgeMessage.WebviewToPluginMessage,
  successCallback?: (...args: any[]) => void,
  errorCallback?: (...args: any[]) => void,
) => {
  if (!isPostMessageBindingSuccessful) {
    setBridgeFn();
  }
  try {
    if (successCallback || errorCallback) {
      if (window?.pluginConfig?.ide === 'jetbrains') {
        console.log('【webview message jetbrains callback】:', payload);
        jsBridgePostMessageWithCallbackFn(
          JSON.stringify(payload),
          successCallback,
          errorCallback,
        );
      }
      if (window?.pluginConfig?.ide === 'vscode') {
        console.log('【webview message vscode callback】:', payload);
        vscodePostMessageFn({
          message: payload,
          successCallback,
          errorCallback,
        });
      }
    } else {
      const timestamp = new Date();
      console.log(
        `${timestamp.getHours()}:${timestamp.getMinutes()}:${timestamp.getSeconds()}.${timestamp.getMilliseconds()}【webview message】:`,
        payload,
      );
      jsBridgePostMessageFn(JSON.stringify(payload));
    }
  } catch (e) {
    console.error(e);
  }
};

export enum JsBridgeErrorReason {
  TIMEOUT = '请求超时，请重试',
  PARSE_ERROR = '解析响应错误',
  UNKNOWN = '未知错误',
  CANCEL = '用户取消',
}

export const jsBridgePostMessageWithCallback = async <T extends any = any>(
  payload: JsBridgeMessage.WebviewToPluginMessage,
  timeout: number = 5000,
): Promise<{
  /** 非业务异常 */
  exception: boolean;
  /** 业务是否成功 */
  success: boolean;
  reason?: string;
  data: T;
}> => {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      resolve({
        exception: true,
        success: false,
        reason: JsBridgeErrorReason.TIMEOUT,
        data: undefined as T,
      });
    }, timeout);
    jsBridgePostMessage(
      payload,
      (res) => {
        clearTimeout(timer);
        try {
          const resObj = JSON.parse(res);
          console.log('【IDE message Callback Success】:', resObj);
          if (resObj.data) {
            resolve({
              ...resObj,
              data: JSON.parse(resObj.data),
              exception: false,
            });
          } else {
            resolve({
              ...resObj,
              exception: false,
            });
          }
        } catch (e) {
          resolve({
            exception: true,
            success: false,
            data: undefined as T,
            reason: JsBridgeErrorReason.PARSE_ERROR,
          });
        }
      },
      (err) => {
        console.log('【IDE message Callback Error】:', err);
        clearTimeout(timer);
        try {
          const errObj = JSON.parse(err);
          resolve({
            ...errObj,
            exception: false,
          });
        } catch (e) {
          resolve({
            exception: true,
            success: false,
            data: undefined as T,
            reason: JsBridgeErrorReason.PARSE_ERROR,
          });
        }
      },
    );
  });
};

export const dig = (event: string, data: Record<string, any> = {}) => {
  jsBridgePostMessage({
    command: 'dig',
    data: {
      event,
      data: {
        ...data,
        timeStamp: Date.now(),
      },
    },
  });
};

export default jsBridgePostMessage;
