import { StateCreator } from 'zustand';
import { StoreActions, StoreState } from './types';

export const actions: StateCreator<
  StoreState & StoreActions,
  [],
  [],
  StoreActions
> = (set, get) => ({
  // 设定chat窗口
  setChatList: (list) => {
    set(() => ({
      chatList: [...list],
    }));
  },
  // 设定chat当前聊天窗口的消息列表
  setChatMessageList: (chatId, list) => {
    set((state) => ({
      chatMessageList: {
        ...state.chatMessageList,
        [chatId]: list,
      },
    }));
  },
  // ide选中代码片段
  setSelectedCode: (selectCodeInfo) => {
    set(() => ({
      selectedCode: {
        ...selectCodeInfo,
      },
    }));
  },
});
